        function toggleLanguage() {lang = lang === "de" ? "en" : "de"; localStorage.setItem("it-demo-language", lang); render()}
        function translateDOM(root) {
            if (lang !== "en") return;
            const walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT);
            let n; while (n = walker.nextNode()) {let t = n.nodeValue.trim(); if (translations[t]) n.nodeValue = n.nodeValue.replace(t, translations[t]);}
            root.querySelectorAll("input[placeholder],textarea[placeholder]").forEach(el => {if (translations[el.placeholder]) el.placeholder = translations[el.placeholder]});
            root.querySelectorAll("button").forEach(b => {if (b.textContent.trim() === "DE / EN") b.textContent = "EN / DE"});
        }

        function render() {if (page === "new" && currentRole !== "reporter") page = "dashboard"; renderNav(); updateTopbar(); let v = $("#view"); if (page === "dashboard") v.innerHTML = dashboard(); else if (page === "incidents") v.innerHTML = incidentList(); else if (page === "new") v.innerHTML = incidentForm(); else if (page === "detail") v.innerHTML = detailPage(); else if (page === "resolve") v.innerHTML = resolvePage(); else if (page === "delegate") v.innerHTML = delegatePage(); else if (page === "close") v.innerHTML = closePage(); else if (page === "reports") v.innerHTML = reportsPage(); else if (page === "settings") v.innerHTML = settingsPage(); else v.innerHTML = dashboard(); translateDOM(v); if (page === "reports") updateReports()}
        function updateTopbar(){const rp=$("#rolePicker");if(rp)rp.value=currentRole;const user=currentRole==="reporter"?currentUser:(currentRole==="leader"?teamLeader:currentUser);const ul=$("#currentUserLabel"), av=$("#currentAvatar");if(ul)ul.textContent=user;if(av)av.textContent=user.split(/\s+/).map(x=>x[0]).slice(0,2).join("").toUpperCase();const fresh=incidents.filter(i=>i.status==="New").length;const n=$("#notificationCount");if(n){n.textContent=fresh>0?fresh:"";n.style.display=fresh>0&&currentRole!=="reporter"?"grid":"none"}const b=$("#notificationBell");if(b)b.style.display=currentRole==="reporter"?"none":"inline-flex"}
        function changeRole(role){currentRole=role;currentUser=role==="reporter"?(reporters.includes(currentUser)?currentUser:reporters[0]):role==="leader"?teamLeader:(supporters.includes(currentUser)?currentUser:supporters[0]);localStorage.setItem("it-demo-role",currentRole);localStorage.setItem("it-demo-user",currentUser);render()}
        function showNotifications(){incidentListMode="new";setPage("incidents")}
        function chooseReporter(name){currentUser=name;localStorage.setItem("it-demo-user",name);render()}
        function dateKey(d){return new Date(d).toISOString().slice(0,10)}
        function dashboard(){
            if(currentRole==="reporter"){
                const mine=incidents.filter(i=>i.reporter===currentUser), active=mine.filter(i=>i.status!=="Closed"), closed=mine.filter(i=>i.status==="Closed");
                const closedCats=categories.map(c=>[c,closed.filter(i=>i.category===c).length]).filter(x=>x[1]>0).sort((a,b)=>b[1]-a[1]); const maxClosed=Math.max(1,...closedCats.map(x=>x[1]));
                return head(lang==="en"?"My Dashboard":"Mein Dashboard",lang==="en"?"Your reported incidents and their current status.":"Deine gemeldeten Incidents und ihr aktueller Status.",`<button class="btn primary" onclick="setPage('new')">＋ ${lang==="en"?"Create incident":"Neuer Incident"}</button><select class="rolepicker" onchange="chooseReporter(this.value)">${reporters.map(r=>`<option ${r===currentUser?"selected":""}>${r}</option>`).join("")}</select>`)+`<div class="cards">${metric(lang==="en"?"Not closed":"Nicht geschlossene Incidents",active.length,lang==="en"?"Your active list":"Deine aktive Liste","◷")}${metric(lang==="en"?"Closed incidents":"Geschlossene Incidents",closed.length,lang==="en"?"All closed reports":"Alle geschlossenen Meldungen","✓")}</div><div class="card"><div class="pagehead"><h2>${lang==="en"?"My open / active incidents":"Meine offenen / aktiven Incidents"}</h2></div>${tableRows(active)}</div><div class="card" style="margin-top:16px"><h2>${lang==="en"?"Closed incidents by category":"Geschlossene Incidents nach Kategorie"}</h2>${closedCats.length?closedCats.map(x=>`<div class="detailrow"><span>${x[0]}</span><strong>${x[1]}</strong></div>`).join(""): (lang==="en"?"No closed incidents yet.":"Noch keine geschlossenen Incidents.")}</div>`;
            }
            if(currentRole==="supporter"){
                const open=incidents.filter(i=>["New","In Progress","Delegated"].includes(i.status));
                const today=dateKey(new Date()), start=new Date();start.setDate(start.getDate()-start.getDay()+1);start.setHours(0,0,0,0);const weekStart=dateKey(start);
                const resolved=incidents.filter(i=>i.resolutionSource!=="Reporter"&&i.resolvedBy&&i.resolvedAt);const todayCount=resolved.filter(i=>dateKey(i.resolvedAt)===today).length;const weekCount=resolved.filter(i=>dateKey(i.resolvedAt)>=weekStart&&dateKey(i.resolvedAt)<=today).length;
                return head(lang==="en"?"Support Dashboard":"Support-Dashboard",lang==="en"?"Open workload and direct Support resolutions.":"Offene Arbeit und direkte Lösungen durch Support.",`<button class="btn primary" onclick="incidentListMode='open';setPage('incidents')">${lang==="en"?"View open incidents":"Offene Incidents anzeigen"}</button>`)+`<div class="cards"><button class="card clickablemetric" onclick="incidentListMode='open';setPage('incidents')">${metric(lang==="en"?"Open incidents":"Offene Incidents",open.length,lang==="en"?"Click to open list":"Klicken für die Liste","◷")}</button>${metric(lang==="en"?"Resolved today":"Heute gelöst",todayCount,lang==="en"?"Directly by Support":"Direkt durch Support","✓")}${metric(lang==="en"?"Resolved this week":"Diese Woche gelöst",weekCount,lang==="en"?"Directly by Support":"Direkt durch Support","✓")}</div><div class="card"><h2>${lang==="en"?"Resolved by Support in date range":"Durch Support gelöst im Zeitraum"}</h2><div class="filters"><label>${lang==="en"?"From":"Von"} <input type="date" id="rangeFrom" onchange="updateRangeCount()"></label><label>${lang==="en"?"To":"Bis"} <input type="date" id="rangeTo" onchange="updateRangeCount()"></label></div><div class="metric" id="rangeCount">0</div><div class="sub">${lang==="en"?"Only direct resolutions by Support are counted.":"Es zählen nur direkte Lösungen durch Support."}</div></div><div class="card" style="margin-top:16px"><h2>${lang==="en"?"New incidents":"Neue Incidents"}</h2>${tableRows(incidents.filter(i=>i.status==="New"))}</div>`;
            }
            let open=incidents.filter(i=>["New","In Progress","Delegated"].includes(i.status)).length;
            return head("Dashboard", "Übersicht für Teamleitung · Demo-Auswertung", `<button class="btn primary" onclick="setPage('incidents')">Incidents anzeigen</button>`)+`<div class="cards">${metric("Offene Incidents",open,"Neu, in Bearbeitung oder delegiert","◷")}${metric("Alle Incidents",incidents.length,"Gesamter Demo-Bestand","▤")}</div><div class="grid2"><div class="card"><h2>Incidents nach Kategorie</h2>${categories.map(c=>`<div class="detailrow"><span>${c}</span><strong>${incidents.filter(i=>i.category===c).length}</strong></div>`).join("")}</div><div class="card"><h2>Letzte Incidents</h2>${tableRows([...incidents].sort((a,b)=>b.date.localeCompare(a.date)).slice(0,6))}</div></div>`;
        }
        function updateRangeCount(){const a=$("#rangeFrom")?.value,b=$("#rangeTo")?.value;const count=incidents.filter(i=>i.resolutionSource!=="Reporter"&&i.resolvedBy&&i.resolvedAt&&(!a||dateKey(i.resolvedAt)>=a)&&(!b||dateKey(i.resolvedAt)<=b)).length;const el=$("#rangeCount");if(el)el.textContent=count}
        function tableRows(list) {if (!list.length) return `<div class="empty">${lang === "en" ? "No incidents found." : "Keine Incidents gefunden."}</div>`; return `<div class="tablewrap"><table><thead><tr><th>${lang === "en" ? "Reference" : "Referenz"}</th><th>${lang === "en" ? "Created" : "Erstellt"}</th><th>${lang === "en" ? "Description" : "Beschreibung"}</th><th>${lang === "en" ? "Workplace" : "Arbeitsplatz"}</th><th>${lang === "en" ? "Category" : "Kategorie"}</th><th>${lang === "en" ? "Status" : "Status"}</th><th>${lang === "en" ? "Assigned to" : "Zugewiesen an"}</th></tr></thead><tbody>${list.map(i => `<tr class="incident-row" tabindex="0" role="link" aria-label="${lang === "en" ? "Open incident" : "Incident öffnen"} ${escapeHtml(i.id)}" onclick="openIncident('${i.id}')" onkeydown="if(event.key==='Enter'||event.key===' '){event.preventDefault();openIncident('${i.id}')}" title="${lang === "en" ? "Open incident details" : "Incidentdetails öffnen"}"><td class="id">${escapeHtml(i.id)}</td><td>${fmt(i.date)}</td><td>${escapeHtml(i.description)}</td><td>${escapeHtml(i.workplace)}</td><td>${escapeHtml(i.category)}</td><td>${badge(i.status)}</td><td>${escapeHtml(i.assignee)}</td></tr>`).join("")}</tbody></table></div>`}
        function incidentList() {
            const createButton=currentRole==="reporter"?`<button class="btn primary" onclick="setPage('new')">＋ ${lang==="en"?"New incident":"Neuer Incident"}</button>`:"";
            const tabs=[['all',lang==="en"?"All incidents":"Alle Incidents"],['open',lang==="en"?"Open":"Offen"],['new',lang==="en"?"New":"Neu"],['resolved',lang==="en"?"Resolved":"Gelöst"],['closed',lang==="en"?"Closed":"Geschlossen"]];
            return head("Incidents",lang==="en"?"All reported and handled incidents.":"Alle gemeldeten und bearbeiteten Incidents.",createButton)+`<div class="pilltabs incident-view-tabs">${tabs.map(([key,label])=>`<button class="${incidentListMode===key?"active":""}" onclick="setIncidentListMode('${key}')">${label} <span>(${incidentCountForMode(key)})</span></button>`).join("")}</div><div class="filters"><input id="fsearch" placeholder="${lang==="en"?"Search …":"Suchen …"}" oninput="filterTable()"><select id="fstatus" onchange="filterTable()"><option value="">${lang==="en"?"All statuses":"Alle Status"}</option>${["New","In Progress","Delegated","Resolved","Closed"].map(s=>`<option value="${s}">${statusDE(s)}</option>`).join("")}</select><select id="fwork" onchange="filterTable()"><option value="">${lang==="en"?"All workplaces":"Alle Arbeitsplätze"}</option>${workplaces.map(w=>`<option>${w}</option>`).join("")}</select><select id="fcat" onchange="filterTable()"><option value="">${lang==="en"?"All categories":"Alle Kategorien"}</option>${categories.map(c=>`<option>${c}</option>`).join("")}</select><select id="fassignee" onchange="filterTable()"><option value="">${lang==="en"?"All assignees":"Alle Zuständigen"}</option><option value="Nicht zugewiesen">${lang==="en"?"Unassigned":"Nicht zugewiesen"}</option>${supporters.map(person=>`<option value="${escapeHtml(person)}">${escapeHtml(person)}</option>`).join("")}</select><button class="btn" onclick="resetFilters()">${lang==="en"?"Reset":"Zurücksetzen"}</button></div><div id="incidenttable">${tableRows(getFilteredIncidents())}</div><p class="sub" id="incidentCountNote" style="margin-top:12px"></p>`
        }
        function incidentCountForMode(mode){return incidents.filter(i=>mode==="all"||(mode==="open"&&["New","In Progress","Delegated"].includes(i.status))||(mode==="new"&&i.status==="New")||(mode==="resolved"&&i.status==="Resolved")||(mode==="closed"&&i.status==="Closed")).length}
        function setIncidentListMode(mode){incidentListMode=mode;filterTable()}
        function getFilteredIncidents(){const q=($("#fsearch")?.value||"").toLowerCase(),s=$("#fstatus")?.value||"",w=$("#fwork")?.value||"",c=$("#fcat")?.value||"",a=$("#fassignee")?.value||"";return incidents.filter(i=>(incidentListMode==="all"||(incidentListMode==="open"&&["New","In Progress","Delegated"].includes(i.status))||(incidentListMode==="new"&&i.status==="New")||(incidentListMode==="resolved"&&i.status==="Resolved")||(incidentListMode==="closed"&&i.status==="Closed"))&&(!q||[i.id,i.description,i.reporter,i.assignee].join(" ").toLowerCase().includes(q))&&(!s||i.status===s)&&(!w||i.workplace===w)&&(!c||i.category===c)&&(!a||i.assignee===a))}
        function filterTable(){const list=getFilteredIncidents();const table=$("#incidenttable");if(table)table.innerHTML=tableRows(list);const note=$("#incidentCountNote");if(note)note.textContent=`${list.length} ${lang==="en"?"incidents shown · Click any row to open it.":"Incidents angezeigt · Klicke auf eine Zeile, um sie zu öffnen."} ${lang==="en"?"Demo data is stored locally in this browser.":"Demo-Daten werden lokal im Browser gespeichert."}`;document.querySelectorAll('.incident-view-tabs button').forEach((b,index)=>b.classList.toggle('active',['all','open','new','resolved','closed'][index]===incidentListMode))}
        function resetFilters(){["fsearch","fstatus","fwork","fcat","fassignee"].forEach(id=>{const el=$("#"+id);if(el)el.value=""});setIncidentListMode("all")}
        function incidentForm() {return head("Neuer Incident", "Erfasse ein Problem in wenigen Schritten.") + `<div class="card"><form onsubmit="createIncident(event)"><div class="formgrid"><div class="field"><label>Arbeitsplatz <span class="required">*</span></label><select name="workplace" required>${workplaces.map(x => `<option>${x}</option>`).join("")}</select></div><div class="field"><label>Kategorie <span class="required">*</span></label><select name="category" required>${categories.map(x => `<option>${x}</option>`).join("")}</select></div><div class="field"><label>Priorität</label><select name="priority"><option>Niedrig</option><option selected>Mittel</option><option>Hoch</option></select></div><div class="field"><label>Gemeldet von</label><select name="reporter">${reporters.map(x => `<option ${currentRole==="reporter"&&x===currentUser?"selected":""}>${x}</option>`).join("")}</select></div></div><div class="field"><label>Problembeschreibung <span class="required">*</span></label><textarea name="description" maxlength="500" placeholder="Bitte beschreibe das Problem so genau wie möglich …" required></textarea></div><div class="formactions"><button type="button" class="btn" onclick="setPage('incidents')">Abbrechen</button><button class="btn primary">Incident erstellen</button></div></form></div>`}
        function createIncident(e) {e.preventDefault(); let f = new FormData(e.target); let id = "INC-" + (1009 + Math.max(0, ...incidents.map(i => Number(i.id.slice(4)) - 1008))); let i = {id, date: new Date().toISOString().slice(0, 16), workplace: f.get("workplace"), category: f.get("category"), description: f.get("description"), status: "New", priority: f.get("priority"), assignee: "Nicht zugewiesen", reporter: f.get("reporter"), resolution: "", events: [addEvent("Incident erstellt", f.get("reporter"))]}; incidents.unshift(i); persist(); selectedId = id; toast(`${id} wurde erstellt`); setPage("detail")}
        function openIncident(id) {selectedId = id; setPage("detail")}
        function current() {return incidents.find(i => i.id === selectedId) || incidents[0]}
        function detailPage() {
            let i = current(); if (!i) return incidentList();
            const isReporterOwner = currentRole === "reporter" && i.reporter === currentUser;
            const isSupporter = currentRole === "supporter";
            const isOpen = !["Resolved", "Closed"].includes(i.status);
            const assignedToMe = i.assignee === currentUser;
            let actionPanel = "";
            if (isSupporter && isOpen) {
                if (!assignedToMe) {
                    actionPanel = `<div class="card"><h2>${lang === "en" ? "Actions" : "Aktionen"}</h2><p class="sub">${lang === "en" ? "Take ownership to start working on this incident." : "Übernimm den Incident, um mit der Bearbeitung zu beginnen."}</p><button class="btn primary" style="width:100%;padding:13px" onclick="takeOverIncident()">${lang === "en" ? "Take over task" : "Aufgabe übernehmen"}</button></div>`;
                } else {
                    actionPanel = `<div class="card"><h2>${lang === "en" ? "Actions" : "Aktionen"}</h2><button class="tile" style="width:100%;min-height:135px" onclick="setPage('resolve')"><div class="bigico" style="color:var(--green)">✓</div><strong>${lang === "en" ? "Resolve incident" : "Incident lösen"}</strong><p>${lang === "en" ? "Record the outcome and what you did" : "Ergebnis und durchgeführte Schritte dokumentieren"}</p></button><div class="notice" style="margin-top:12px">${lang === "en" ? "You can note that the issue resolved itself, describe the action taken, and record if you informed an external person or team." : "Du kannst festhalten, dass sich das Problem selbst gelöst hat, deine Massnahmen beschreiben und dokumentieren, ob du eine externe Person oder ein Team informiert hast."}</div></div>`;
                }
            } else if (isReporterOwner && isOpen) {
                actionPanel = `<div class="card"><h2>${lang === "en" ? "Actions" : "Aktionen"}</h2><p class="sub">${lang === "en" ? "If the issue is fixed, you can mark it as resolved." : "Wenn das Problem behoben ist, kannst du es als gelöst markieren."}</p><button class="btn primary" onclick="markReporterResolved()">${lang === "en" ? "Mark as resolved" : "Als gelöst markieren"}</button></div>`;
            } else if (i.status === "Resolved" && (isReporterOwner || isSupporter)) {
                actionPanel = `<div class="card"><h2>${lang === "en" ? "Actions" : "Aktionen"}</h2><p class="sub">${lang === "en" ? "This incident is resolved but not yet closed. You can close it when the follow-up is complete." : "Dieser Incident ist gelöst, aber noch nicht geschlossen. Du kannst ihn schliessen, sobald die Nachbearbeitung abgeschlossen ist."}</p><button class="btn primary" onclick="closeIncident()">${lang === "en" ? "Mark as closed" : "Als geschlossen markieren"}</button></div>`;
            }
            return head(`${i.id} &nbsp; ${badge(i.status)}`, i.description, `<button class="btn" onclick="setPage('incidents')">← ${lang === "en" ? "Back" : "Zurück"}</button>`) + `<div class="detailgrid"><div class="card"><div class="pilltabs"><button class="active">${lang === "en" ? "Overview" : "Übersicht"}</button><button onclick="showActivity()">${lang === "en" ? "Activity" : "Aktivitäten"}</button></div><div class="detailrow"><span>${lang === "en" ? "Workplace" : "Arbeitsplatz"}</span><strong>${escapeHtml(i.workplace)}</strong></div><div class="detailrow"><span>${lang === "en" ? "Category" : "Kategorie"}</span><strong>${escapeHtml(i.category)}</strong></div><div class="detailrow"><span>${lang === "en" ? "Priority" : "Priorität"}</span><strong>${escapeHtml(i.priority)}</strong></div><div class="detailrow"><span>${lang === "en" ? "Description" : "Beschreibung"}</span><strong>${escapeHtml(i.description)}</strong></div><div class="detailrow"><span>${lang === "en" ? "Created" : "Erstellt"}</span><strong>${fmt(i.date)}</strong></div><div class="detailrow"><span>${lang === "en" ? "Reported by" : "Erstellt von"}</span><strong>${escapeHtml(i.reporter)}</strong></div><div class="detailrow"><span>${lang === "en" ? "Assigned to" : "Zugewiesen an"}</span><strong>${escapeHtml(i.assignee)}</strong></div>${i.resolution ? `<div class="detailrow"><span>${lang === "en" ? "Resolution" : "Lösung"}</span><strong>${escapeHtml(i.resolution)}</strong></div>` : ""}${i.delegatedTo ? `<div class="detailrow"><span>${lang === "en" ? "Informed" : "Informiert"}</span><strong>${escapeHtml(i.delegatedTo)}</strong></div>` : ""}${i.delegationNote ? `<div class="detailrow"><span>${lang === "en" ? "Note" : "Hinweis"}</span><strong>${escapeHtml(i.delegationNote)}</strong></div>` : ""}</div>${actionPanel}<div class="card" id="activitycard" style="margin-top:16px;grid-column:1/-1"><h2>${lang === "en" ? "Activity" : "Aktivitäten"}</h2><div class="timeline">${(i.events || []).slice().reverse().map(e => `<div class="event"><div class="eventmark">✓</div><div class="eventbody"><strong>${escapeHtml(e[0])}</strong><small>${fmt(e[2])} · ${escapeHtml(e[1])}</small></div></div>`).join("")}</div></div></div>`;
        }
        function takeOverIncident() { const i = current(); if (!i || currentRole !== "supporter" || ["Resolved", "Closed"].includes(i.status)) return; i.assignee = currentUser; i.status = "In Progress"; i.events.push(addEvent("Bearbeitung übernommen", currentUser)); persist(); toast(lang === "en" ? "You have taken over this incident" : "Incident wurde übernommen"); render(); }
        
        function showActivity() {$("#activitycard")?.scrollIntoView({behavior: "smooth"})}
        function assignIncident() {let i = current(); i.assignee = $("#assignTo").value; i.status = i.status === "New" ? "In Progress" : i.status; i.events.push(addEvent("Supporter zugewiesen: " + i.assignee)); persist(); toast("Zuweisung gespeichert"); render()}
        function resolvePage() {
            let i = current();
            const en = lang === "en";
            return head(en ? "Resolve incident" : "Incident lösen", `${i.id} · ${en ? "Record the outcome" : "Ergebnis dokumentieren"}`) + `<div class="card" style="max-width:850px"><form onsubmit="resolveIncident(event)">
                <div class="field"><label>${en ? "What happened?" : "Was ist passiert?"} <span class="required">*</span></label>
                    <label style="font-weight:500;display:flex;gap:9px;align-items:flex-start"><input type="radio" name="outcome" value="self_resolved" checked onchange="toggleResolutionFields()" style="width:auto;margin-top:3px"> <span>${en ? "The problem resolved itself; no action was needed." : "Das Problem hat sich von selbst gelöst; es war keine Massnahme nötig."}</span></label>
                    <label style="font-weight:500;display:flex;gap:9px;align-items:flex-start"><input type="radio" name="outcome" value="action_taken" onchange="toggleResolutionFields()" style="width:auto;margin-top:3px"> <span>${en ? "I took action to resolve the problem." : "Ich habe eine Massnahme zur Lösung des Problems durchgeführt."}</span></label>
                </div>
                <div class="field" id="resolutionDescriptionField" style="display:none"><label>${en ? "Resolution description" : "Beschreibung der Lösung"} <span class="required">*</span></label><div class="sub">${en ? "Optional source examples (original German wording)" : "Optionale Beispiele aus den Quelldaten (Originalwortlaut)"}</div><div style="display:flex;gap:8px;flex-wrap:wrap"><input id="resolutionExample" list="resolutionExampleList" placeholder="${en ? "Search example descriptions…" : "Beispielbeschreibung suchen …"}" style="flex:1;min-width:220px"><datalist id="resolutionExampleList">${resolutionExamples.map(x => `<option value="${escapeHtml(x)}"></option>`).join("")}</datalist><button type="button" class="btn" onclick="applyResolutionExample()">${en ? "Use example" : "Beispiel übernehmen"}</button></div><textarea id="resolutionDescription" name="resolution" maxlength="700" placeholder="${en ? "Describe what you did to resolve the issue…" : "Beschreibe, was du zur Lösung des Problems gemacht hast …"}"></textarea></div>
                <div class="field"><label style="font-weight:600;display:flex;gap:9px;align-items:flex-start"><input type="checkbox" name="informedExternal" id="informedExternal" value="yes" onchange="toggleResolutionFields()" style="width:auto;margin-top:3px"> <span>${en ? "I informed an external person or team" : "Ich habe eine externe Person oder ein anderes Team informiert"}</span></label></div>
                <div id="externalInfoFields" style="display:none"><div class="field"><label>${en ? "Person or team informed" : "Informierte Person oder Team"} <span class="required">*</span></label><input name="target" id="externalTarget" maxlength="120" placeholder="${en ? "e.g. electrician, Don't Panic team" : "z. B. Elektriker, Don't Panic Team"}"></div><div class="field"><label>${en ? "What information did you pass on?" : "Welche Information hast du weitergegeben?"} <span class="required">*</span></label><textarea name="delegationInfo" id="delegationInfo" maxlength="500" placeholder="${en ? "Describe briefly what you reported or agreed…" : "Beschreibe kurz, was du gemeldet oder vereinbart hast …"}"></textarea></div></div>
                <div class="field"><label>${en ? "Resolved by" : "Gelöst von"}</label><input value="${escapeHtml(currentUser)}" disabled><input type="hidden" name="actor" value="${escapeHtml(currentUser)}"></div>
                <div class="notice">${en ? "The incident will be marked resolved when saved. If you informed another team, only the information you enter here is recorded; their work is not tracked." : "Beim Speichern wird der Incident als gelöst markiert. Wenn du ein anderes Team informiert hast, wird nur die hier erfasste Information dokumentiert; dessen Arbeit wird nicht nachverfolgt."}</div>
                <div class="formactions"><button type="button" class="btn" onclick="setPage('detail')">${en ? "Cancel" : "Abbrechen"}</button><button class="btn primary">${en ? "Save resolution" : "Lösung speichern"}</button></div></form></div>`;
        }
        function applyResolutionExample() {
            const example = $("#resolutionExample")?.value || "";
            if (!example || !resolutionExamples.includes(example)) {
                toast(lang === "en" ? "Choose one of the source examples" : "Bitte ein Beispiel aus den Quelldaten auswählen");
                return;
            }
            const description = $("#resolutionDescription");
            if (description) description.value = example;
            const action = document.querySelector('input[name="outcome"][value="action_taken"]');
            if (action) action.checked = true;
            toggleResolutionFields();
        }
        function toggleResolutionFields() {
            const outcome = document.querySelector('input[name="outcome"]:checked')?.value || "self_resolved";
            const actionField = $("#resolutionDescriptionField"), desc = $("#resolutionDescription");
            const informed = $("#informedExternal")?.checked || false;
            const externalFields = $("#externalInfoFields"), target = $("#externalTarget"), info = $("#delegationInfo");
            if (actionField) actionField.style.display = outcome === "action_taken" ? "block" : "none";
            if (desc) desc.required = outcome === "action_taken";
            if (externalFields) externalFields.style.display = informed ? "block" : "none";
            if (target) target.required = informed;
            if (info) info.required = informed;
        }
        function resolveIncident(e) {
            e.preventDefault();
            const f = new FormData(e.target), i = current();
            const outcome = f.get("outcome");
            const informed = f.get("informedExternal") === "yes";
            const description = outcome === "action_taken" ? String(f.get("resolution") || "").trim() : (lang === "en" ? "The problem resolved itself; no action was needed." : "Das Problem hat sich von selbst gelöst; es war keine Massnahme nötig.");
            i.resolution = description;
            i.resolvedBy = currentUser;
            i.resolvedAt = new Date().toISOString();
            i.resolutionSource = "Support";
            // Resolution and closure are separate lifecycle steps. Every resolution
            // remains Resolved until a reporter or supporter explicitly closes it.
            i.status = "Resolved";
            if (informed) {
                i.delegatedTo = String(f.get("target") || "").trim();
                i.delegationNote = String(f.get("delegationInfo") || "").trim();
                i.events.push(addEvent((lang === "en" ? "External person/team informed: " : "Externe Person/Team informiert: ") + i.delegatedTo + " — " + i.delegationNote, currentUser));
            }
            i.events.push(addEvent(outcome === "self_resolved" ? (lang === "en" ? "Resolved by Support — issue resolved itself" : "Durch Support gelöst — Problem hat sich selbst gelöst") : (lang === "en" ? "Resolved directly by Support" : "Direkt durch Support gelöst") + (informed ? (lang === "en" ? " (external party informed)" : " (externe Stelle informiert)") : ""), currentUser));
            i.closedAt = null;
            i.events.push(addEvent(lang === "en" ? "Awaiting explicit closure" : "Wartet auf explizite Schliessung", currentUser));
            persist(); toast(lang === "en" ? "Incident resolved — ready to be closed" : "Incident gelöst — kann geschlossen werden"); setPage("detail");
        }
        function delegatePage() {let i = current(); return head("Delegieren / Informieren", `${i.id} · Die externe Arbeit wird nicht weiterverfolgt`) + `<div class="card" style="max-width:850px"><form onsubmit="delegateIncident(event)"><div class="field"><label>${lang === "en" ? "Person or team informed" : "Informierte Person oder Team"} <span class="required">*</span></label><input name="target" required maxlength="120" placeholder="${lang === "en" ? "e.g. electrician, Don't Panic team, network team" : "z. B. Elektriker, Don't Panic Team, Netzwerk-Team"}"></div><div class="field"><label>Kurzer Hinweis (optional)</label><textarea name="note" maxlength="300" placeholder="z. B. Fehler gemeldet, zuständige Person informiert …"></textarea></div><div class="notice">Der Incident bleibt ungelöst/offen, bis jemand ihn als gelöst markiert. Es gibt keine Nachverfolgung des externen Auftrags.</div><div class="formactions"><button type="button" class="btn" onclick="setPage('detail')">Abbrechen</button><button class="btn primary">Delegation speichern</button></div></form></div>`}
        function delegateIncident(e) {e.preventDefault(); let f = new FormData(e.target), i = current(); i.status = "Delegated"; i.delegatedTo = f.get("target"); i.delegationNote = f.get("note"); i.events.push(addEvent("Informiert: " + i.delegatedTo)); persist(); toast("Delegation dokumentiert"); setPage("detail")}
        function markReporterResolved() {let i = current(); i.status = "Resolved"; i.resolutionSource = "Reporter"; i.resolvedBy = i.reporter; i.resolvedAt = new Date().toISOString(); i.events.push(addEvent("Durch Reporter als gelöst markiert", i.reporter)); persist(); toast("Als durch Reporter gelöst markiert"); render()}
        function closePage() {let i = current(); return head("Incident schliessen", `${i.id} · Lifecycle beenden`) + `<div class="card" style="max-width:700px"><h2>Incident schliessen?</h2><p>Der Incident wird als geschlossen markiert. Die Schliessung ist getrennt von einer Lösung durch Support.</p>${!["Resolved", "Closed"].includes(i.status) ? `<div class="notice">Dieser Incident ist noch nicht als gelöst markiert. Möchtest du ihn trotzdem schliessen? Für die Demo ist das möglich.</div>` : ""}<div class="formactions"><button class="btn" onclick="setPage('detail')">Abbrechen</button><button class="btn primary" onclick="closeIncident()">Incident schliessen</button></div></div>`}
        function closeIncident() {
            let i = current();
            if (!i || i.status !== "Resolved") {
                toast(lang === "en" ? "Only resolved incidents can be closed" : "Nur gelöste Incidents können geschlossen werden");
                return;
            }
            const allowed = currentRole === "supporter" || (currentRole === "reporter" && i.reporter === currentUser);
            if (!allowed) {
                toast(lang === "en" ? "Only the assigned reporter or a supporter can close this incident" : "Nur der zuständige Reporter oder ein Supporter kann diesen Incident schliessen");
                return;
            }
            i.status = "Closed";
            i.closedAt = new Date().toISOString();
            i.events.push(addEvent(lang === "en" ? "Incident closed" : "Incident geschlossen", currentUser));
            persist();
            toast(lang === "en" ? "Incident closed" : "Incident geschlossen");
            setPage("detail");
        }
        function reportDurationMs(i) { const start = new Date(i.date).getTime(), end = new Date(i.resolvedAt).getTime(); return Number.isFinite(start) && Number.isFinite(end) && end >= start ? end - start : null; }
        function reportDurationLabel(ms) { if (ms == null) return "–"; const mins = Math.round(ms / 60000); if (mins < 60) return `${mins} min`; const hours = Math.floor(mins / 60), rest = mins % 60; if (hours < 24) return `${hours}h ${rest}m`; return `${Math.floor(hours / 24)}d ${hours % 24}h`; }
        function reportDateValue(d) { return d ? new Date(d).toISOString().slice(0, 10) : ""; }
        function updateReports() { const from = $("#reportFrom")?.value || "", to = $("#reportTo")?.value || ""; const resolved = incidents.filter(i => i.resolvedAt && ["Resolved", "Closed"].includes(i.status) && (!from || reportDateValue(i.resolvedAt) >= from) && (!to || reportDateValue(i.resolvedAt) <= to)); const supportResolved = resolved.filter(i => i.resolutionSource !== "Reporter" && i.resolvedBy); const durations = supportResolved.map(i => reportDurationMs(i)).filter(x => x != null); const total = durations.reduce((a,b) => a+b, 0); const en = lang === "en"; const fmtTotal = reportDurationLabel(total); const metric = (label, value, hint="") => `<div class="reportstat"><strong>${value}</strong><span>${label}</span>${hint ? `<small class="sub">${hint}</small>` : ""}</div>`; const bySupporter = supporters.map(name => { const rows = supportResolved.filter(i => i.resolvedBy === name); const time = rows.map(reportDurationMs).filter(x => x != null).reduce((a,b) => a+b,0); return {name, count: rows.length, time}; }).sort((a,b) => b.count-a.count || b.time-a.time); const categoryCounts = [...new Set(incidents.map(i => i.category))].map(category => ({category, count: resolved.filter(i => i.category === category).length})).filter(x => x.count > 0).sort((a,b) => b.count-a.count || a.category.localeCompare(b.category)); const problemCounts = [...new Set(resolved.map(i => `${i.category} — ${i.description}`))].map(problem => ({problem, count: resolved.filter(i => `${i.category} — ${i.description}` === problem).length})).sort((a,b) => b.count-a.count || a.problem.localeCompare(b.problem)).slice(0,10); const tableRows = supportResolved.slice().sort((a,b) => new Date(b.resolvedAt)-new Date(a.resolvedAt)).map(i => `<tr><td>${escapeHtml(i.id)}</td><td>${escapeHtml(i.category)}</td><td>${escapeHtml(i.description)}</td><td>${escapeHtml(i.resolvedBy || i.assignee || "–")}</td><td>${fmt(i.date)}</td><td>${fmt(i.resolvedAt)}</td><td>${reportDurationLabel(reportDurationMs(i))}</td></tr>`).join(""); const supporterRows = bySupporter.map(x => `<tr><td>${escapeHtml(x.name)}</td><td>${x.count}</td><td>${reportDurationLabel(x.time)}</td><td>${x.count ? reportDurationLabel(x.time/x.count) : "–"}</td></tr>`).join(""); const problemRows = problemCounts.map((x,n) => `<div class="detailrow"><span>#${n+1} ${escapeHtml(x.problem)}</span><strong>${x.count}</strong></div>`).join(""); const categoryRows = categoryCounts.slice(0,10).map((x,n) => `<div class="detailrow"><span>#${n+1} ${escapeHtml(x.category)}</span><strong>${x.count}</strong></div>`).join(""); const el = $("#reportResults"); if (el) el.innerHTML = `<div class="reportstats">${metric(en?"Resolved by Support":"Durch Support gelöst", supportResolved.length)}${metric(en?"Total resolution time":"Gesamte Lösungszeit", fmtTotal, en?"Sum of incident durations":"Summe der Incident-Lösungszeiten")}${metric(en?"Average per incident":"Ø pro Incident", durations.length ? reportDurationLabel(total/durations.length) : "–")}${metric(en?"Reporter-marked resolved":"Durch Reporter gelöst", resolved.filter(i=>i.resolutionSource==="Reporter").length)}</div><div class="grid2" style="margin-top:16px"><div class="card"><h2>${en?"Resolved by supporter":"Gelöste Incidents pro Supporter"}</h2><div class="tablewrap"><table><thead><tr><th>${en?"Supporter":"Supporter"}</th><th>${en?"Resolved":"Gelöst"}</th><th>${en?"Total time":"Gesamtzeit"}</th><th>${en?"Average time":"Ø Zeit"}</th></tr></thead><tbody>${supporterRows}</tbody></table></div></div><div class="card"><h2>${en?"Top recurring problems":"Häufigste Probleme"}</h2><p class="sub">${en?"Ranked by exact category and description in the selected period.":"Sortiert nach identischer Kategorie und Beschreibung im gewählten Zeitraum."}</p>${problemRows || `<p class="sub">${en?"No resolved incidents in this period.":"Keine gelösten Incidents in diesem Zeitraum."}</p>`}<h3 style="margin-top:18px">${en?"Top categories":"Top-Kategorien"}</h3>${categoryRows || `<p class="sub">–</p>`}</div></div><div class="card" style="margin-top:16px"><div class="pagehead"><h2>${en?"Resolution time per incident":"Lösungszeit pro Incident"}</h2><span class="sub">${supportResolved.length} ${en?"support-resolved incidents":"durch Support gelöste Incidents"}</span></div><div class="tablewrap"><table><thead><tr><th>ID</th><th>${en?"Category":"Kategorie"}</th><th>${en?"Problem":"Problem"}</th><th>${en?"Resolved by":"Gelöst von"}</th><th>${en?"Created":"Erstellt"}</th><th>${en?"Resolved":"Gelöst"}</th><th>${en?"Elapsed time":"Dauer"}</th></tr></thead><tbody>${tableRows || `<tr><td colspan="7">${en?"No support-resolved incidents in this date range.":"Keine durch Support gelösten Incidents in diesem Zeitraum."}</td></tr>`}</tbody></table></div></div>`; }
        function reportsPage() { const en = lang === "en"; const today = new Date(); const end = today.toISOString().slice(0,10); const startDate = new Date(today); startDate.setDate(startDate.getDate()-30); const start = startDate.toISOString().slice(0,10); return head(en?"Reports":"Berichte", en?"Team leader overview · resolution volume, recurring issues and time spent":"Übersicht für Teamleitung · Lösungsvolumen, wiederkehrende Probleme und Zeitaufwand", `<button class="btn" onclick="window.print()">⤓ ${en?"Print / PDF":"Drucken / PDF"}</button>`) + `<div class="card"><h2>${en?"Reporting date range":"Auswertungszeitraum"}</h2><div class="filters"><div class="field"><label>${en?"Resolved from":"Gelöst von"}</label><input type="date" id="reportFrom" value="${start}" onchange="updateReports()"></div><div class="field"><label>${en?"Resolved to":"Gelöst bis"}</label><input type="date" id="reportTo" value="${end}" onchange="updateReports()"></div><button class="btn" onclick="setReportRange(7)">${en?"Last 7 days":"Letzte 7 Tage"}</button><button class="btn" onclick="setReportRange(30)">${en?"Last 30 days":"Letzte 30 Tage"}</button><button class="btn" onclick="setReportRange(90)">${en?"Last 90 days":"Letzte 90 Tage"}</button></div><p class="sub">${en?"Resolution time is measured from incident creation to resolution. Supporter workload includes incidents resolved by Support, not incidents marked resolved by the reporter.":"Die Lösungszeit wird von der Incident-Erstellung bis zur Lösung gemessen. Die Supporter-Auswertung zählt durch Support gelöste Incidents, nicht durch Reporter als gelöst markierte Incidents."}</p></div><div id="reportResults"></div><p class="sub" style="margin-top:14px">${en?"Calculated from local demo data; durations are elapsed time, not active working time. Results are illustrative, not audit-ready.":"Berechnet aus lokalen Demodaten; die Dauer ist verstrichene Zeit, keine aktive Arbeitszeit. Die Ergebnisse dienen der Demo und sind nicht revisionssicher."}</p>`; }
        function setReportRange(days) { const end = new Date(), start = new Date(); start.setDate(start.getDate()-days); const f = $("#reportFrom"), t = $("#reportTo"); if(f) f.value=start.toISOString().slice(0,10); if(t) t.value=end.toISOString().slice(0,10); updateReports(); }

        function settingsPage() {return head("Einstellungen", "Konfiguration für die Demo") + `<div class="grid2"><div class="card"><h2>Kategorien verwalten</h2>${categories.map((c, i) => `<div class="detailrow"><span>${c}</span><strong>${incidents.filter(x => x.category === c).length} Incidents</strong></div>`).join("")}<div class="field" style="margin-top:15px"><label>Neue Kategorie (Demo)</label><input id="newcat" placeholder="z. B. Telefonie"></div><button class="btn" onclick="addCategory()">Kategorie hinzufügen</button></div><div class="card"><h2>Demo verwalten</h2><p class="sub">Alle Änderungen werden nur in diesem Browser gespeichert.</p><div class="detailrow"><span>Incidents</span><strong>${incidents.length}</strong></div><div class="detailrow"><span>Speicherung</span><strong>localStorage</strong></div><div class="detailrow"><span>Backend</span><strong>Nicht verbunden</strong></div><div class="detailrow"><span>Arbeitsplätze</span><strong>${workplaces.length}</strong></div><div class="detailrow"><span>Arbeit-Beispiele</span><strong>${resolutionExamples.length} ${lang==="en"?"unique suggestions":"eindeutige Vorschläge"}</strong></div><button class="btn primary" onclick="resetDemo()">Demo-Daten zurücksetzen</button><div class="notice" style="margin-top:16px">Keine echten personenbezogenen oder vertraulichen Daten verwenden. Dies ist ein Mock-up ohne Anmeldung oder Zugriffsschutz.</div></div></div><div class="card"><h2>Benutzer & Rollen (Beispiel)</h2><div class="tablewrap"><table><thead><tr><th>Name</th><th>Rolle</th><th>Status</th></tr></thead><tbody><tr><td>${teamLeader}</td><td>Teamleitung</td><td><span class="badge b-resolved">Aktiv</span></td></tr>${supporters.map(s => `<tr><td>${s}</td><td>Supporter</td><td><span class="badge b-resolved">Aktiv</span></td></tr>`).join("")}${reporters.map(r => `<tr><td>${r}</td><td>Reporter</td><td><span class="badge b-resolved">Aktiv</span></td></tr>`).join("")}</tbody></table></div></div>`}
        function addCategory() {let c = $("#newcat").value.trim(); if (!c) return toast("Bitte Kategorie eingeben"); if (!categories.includes(c)) {categories.push(c); toast("Kategorie nur für diese Sitzung hinzugefügt"); render()} else toast("Kategorie existiert bereits")}
        function resetDemo() {if (confirm("Alle Demo-Änderungen zurücksetzen?")) {incidents = JSON.parse(JSON.stringify(seed)); persist(); toast("Demo-Daten zurückgesetzt"); render()} }
        $("#globalSearch").addEventListener("keydown", e => {if (e.key === "Enter") {setPage("incidents"); setTimeout(() => {let x = $("#fsearch"); if (x) {x.value = e.target.value; filterTable()} }, 0)} });
        render();